   160	export function categoryBars(
   161	  categories: { amount: string | null }[],
   162	  basis: "total" | "maximum",
   163	): { width: number; negative: boolean }[] {
   164	  const scale = Math.max(
   165	    0,
   166	    ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0),
   167	  );
   168	  const values = categories.map(({ amount }) => {
   169	    if (amount === null) return 0n;
   170	    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
   171	    const value = BigInt(whole + fraction.padEnd(scale, "0"));
   172	    return amount.startsWith("-") ? -value : value;
   173	  });
   174	  const magnitudes = values.map((value) => (value < 0n ? -value : value));
   175	  let denominator: bigint;
   176	  let precision: bigint;
   177	  switch (basis) {
   178	    case "total":
   179	      denominator = magnitudes.reduce((total, value) => total + value, 0n);
   180	      precision = 100000000n;
   181	      break;
   182	    case "maximum":
   183	      denominator = magnitudes.reduce(
   184	        (largest, value) => (value > largest ? value : largest),
   185	        0n,
   186	      );
   187	      precision = 100n;
   188	      break;
   189	    default: {
   190	      const exhaustive: never = basis;
   191	      return exhaustive;
   192	    }
   193	  }
   194	  return values.map((value, index) => ({
   195	    negative: value < 0n,
   196	    width:
   197	      denominator === 0n
   198	        ? 0
   199	        : Number((magnitudes[index] * 100n * precision) / denominator) /
   200	          Number(precision),
   201	  }));
   202	}
