 13	function compareAmounts(left: string | null, right: string | null): number {
 14	  if (left === null) return right === null ? 0 : 1;
 15	  if (right === null) return -1;
 16	  const difference = sumAmounts([
 17	    right,
 18	    left.startsWith("-") ? left.slice(1) : `-${left}`,
 19	  ]);
 20	  if (difference === null || /^-?0(?:\.0+)?$/u.test(difference)) return 0;
 21	  return difference.startsWith("-") ? -1 : 1;
 22	}
