 24	function moneySources(details: MemberDetails): MemberMoneySource[] {
 25	  const groups = new Map<
 26	    string | null,
 27	    { source: MemberMoneySource; amounts: string[] }
 28	  >();
 29	  for (const declaration of details.declarations) {
 30	    for (const entry of declaration.entries) {
 31	      const key = entry.funder?.id ?? null;
 32	      let group = groups.get(key);
 33	      if (!group) {
 34	        group = {
 35	          source: {
 36	            funder: entry.funder,
 37	            amount: null,
 38	            entryCount: 0,
 39	            missingGbpAmountCount: 0,
 40	            unknownCurrencyCount: 0,
 41	            foreignCurrencyCount: 0,
 42	          },
 43	          amounts: [],
 44	        };
 45	        groups.set(key, group);
 46	      }
 47	      group.source.entryCount += 1;
 48	      if (entry.currency === "GBP") {
 49	        if (entry.amount === null) group.source.missingGbpAmountCount += 1;
 50	        else group.amounts.push(entry.amount);
 51	      } else if (!entry.currency?.trim())
 52	        group.source.unknownCurrencyCount += 1;
 53	      else group.source.foreignCurrencyCount += 1;
 54	    }
 55	  }
 56	  return Array.from(groups.values(), ({ source, amounts }) => ({
 57	    ...source,
 58	    amount: sumAmounts(amounts),
 59	  })).sort(
 60	    (left, right) =>
 61	      compareAmounts(left.amount, right.amount) ||
 62	      (left.funder?.name ?? "Source unavailable").localeCompare(
 63	        right.funder?.name ?? "Source unavailable",
 64	        "en",
 65	      ) ||
 66	      (left.funder?.id ?? "").localeCompare(right.funder?.id ?? ""),
 67	  );
 68	}
