 71	  if (amount === null) return formatAmount(null);
 72	  const unsigned = amount.replace(/^-/, "");
 73	  const [whole, fraction = ""] = unsigned.split(".");
 74	  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
